71	    fs::path root;
72	    explicit TempArea(const std::string& tag) {
73	        const auto cwd_hash = std::hash<fs::path>{}(fs::current_path());
74	        root = fs::temp_directory_path() /
75	               ("branchaudit_merkle_test_" + tag + "_" +
