98	std::pair<std::string, std::string> silent_merkle(
99	        const std::vector<fs::path>& paths, branchaudit::FileHashResult* out) {
100	    std::stringstream cap_out, cap_err;
101	    auto* old_out = std::cout.rdbuf(cap_out.rdbuf());
102	    auto* old_err = std::cerr.rdbuf(cap_err.rdbuf());
103	    *out = branchaudit::merkle_root_files(paths);
